The quadratic polynomial $P(x),$ with real coefficients, satisfies
\[P(x^3 + x) \ge P(x^2 + 1)\]for all real numbers $x.$  Find the sum of the roots of $P(x).$

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double a, b, c;
    cout << "Enter the coefficients of the quadratic equation (ax^2 + bx + c = 0): " << endl;
    cout << "a: ";
    cin >> a;
    cout << "b: ";
    cin >> b;
    cout << "c: ";
    cin >> c;

    double discriminant = b * b - 4 * a * c;

    if (discriminant < 0) {
        cout << "The quadratic equation has no real roots." << endl;
    } else {
        double root1 = (-b + sqrt(discriminant)) / (2 * a);
        double root2 = (-b - sqrt(discriminant)) / (2 * a);

        cout << "The roots of the quadratic equation are: " << endl;
        cout << "Root 1: " << root1 << endl;
        cout << "Root 2: " << root2 << endl;
    }

